import type { Category } from "@/types/post";

export type ThemeLane =
  | "ai-infrastructure"
  | "global-systems"
  | "macro-economics"
  | "geopolitics-governance"
  | "markets-finance"
  | "industrial-adoption";

export type PipelineCandidate = {
  title: string;
  coreQuestion: string;
  primarySources: string[];
  headlineStatHint: string;
  overlapNotes: string;
  priority: "high" | "medium";
};

export type ThemeDefinition = {
  id: string;
