        for (const e of result.pageErrors) console.log("   ", e.slice(0, 300));
        failed++;
      }
      if (result.consoleErrors.length) {
        console.log("  Console errors:");
        for (const e of result.consoleErrors) console.log("   ", e.slice(0, 300));
